// Before: callbacks
api.fetchUser { result in
    switch result {
    case .success(let user): api.fetchPosts(user.id) { posts in /* ... */ }
    case .failure(let error): show(error)
    }
}

// After: async/await
func loadProfile() async throws -> (User, [Post]) {
    let user = try await api.user()
    async let posts = api.posts(user.id)     // runs in parallel
    async let avatar = api.avatar(user.id)
    return (user, try await posts)
}

// Wrapping a callback API
func currentLocation() async throws -> CLLocation {
    try await withCheckedThrowingContinuation { cont in
        locationProvider.requestOnce { result in cont.resume(with: result) }
    }
}
